import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

// Issue #12: with rate 0 the total must stay as it is today.
test('total with rate 0 on a 10-line cart applies only the 5% bulk discount', () => {
  const items = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(items, 0), 9500); // 10,000 * 0.95
  assert.equal(total(items), 9500);
});

// Issue #12: the customer's discount is applied exactly once.
test('total applies the customer discount once (rate 0.1, 1,000, under 10 lines -> 900)', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('total applies the customer discount, then the 5% bulk discount once (rate 0.1, 10 lines, 10,000 -> 8,550)', () => {
  const items = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(items, 0.1), 8550);
});

test('total gives no bulk discount to a 9-line cart (rate 0.1, 9,000 -> 8,100)', () => {
  const items = Array.from({ length: 9 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(items, 0.1), 8100); // 9,000 * 0.9, no bulk discount
});
